                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="language"
                      label={<span className="font-semibold text-gray-900"> Ngôn ngữ</span>}
                      rules={[{ required: true, message: "Vui lòng chọn ngôn ngữ" }]}
                    >
                      <Select
                        mode="multiple"
                        placeholder="Chọn ngôn ngữ"
                        options={languageOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="version"
                      label={<span className="font-semibold text-gray-900"> Phiên bản</span>}
                      rules={[{ required: true, message: "Vui lòng chọn phiên bản" }]}
                    >
                      <Select
                        placeholder="Chọn phiên bản"
                        options={versionOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="ageRating"
                      label={<span className="font-semibold text-gray-900"> Giới hạn tuổi</span>}
                      rules={[{ required: true, message: "Vui lòng chọn giới hạn tuổi" }]}
                    >
                      <Select
                        placeholder="Chọn giới hạn tuổi"
                        options={ageRatingOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="runningTime"
                      label={<span className="font-semibold text-gray-900">⏰ Thời lượng phim</span>}
                      rules={[{ required: true, message: "Vui lòng nhập thời lượng" }]}
                    >
                      <Input
                        type="number"
                        min={1}
                        placeholder="VD: 120 phút"
                        className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="releaseDate"
                      label={<span className="font-semibold text-gray-900"> Ngày ra mắt</span>}
                      rules={[{ required: true, message: "Vui lòng chọn ngày ra mắt" }]}
                    >
                      <DatePicker 
                        className="w-full rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500" 
                        format="YYYY-MM-DD" 
                      />
                    </Form.Item>
                  </Col>
                </Row>
              </div>
            </Col>
          </Row>
          <Divider className="my-4" />
          <div className="flex gap-3 justify-end">
            <Button 
              onClick={onCancel} 
              disabled={loading} 
              className="border-gray-300 text-gray-700 hover:border-gray-400 hover:text-gray-800"
            >
              Hủy
            </Button>
            <Button 
              type="primary" 
              htmlType="submit" 
              loading={loading}
              className="bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 border-0 shadow-lg"
            >
              Cập nhật phim
            </Button>
          </div>
        </Form>
      )}
    </Modal>
  );
};

export default EditMovie;

import React, { useState, useEffect } from "react";
import {
  Form,
  Input,
  Button,
  Modal,
  DatePicker,
  Upload,
  Select,
  Row,
  Col,
  Divider,
  Spin,
  Table,
  Tag,
  Popconfirm,
  Empty,
  Space,
  Typography,
} from "antd";
import {
  UploadOutlined,
  VideoCameraOutlined,
  PictureOutlined,
  CalendarOutlined,
  ClockCircleOutlined,
  DeleteOutlined,
} from "@ant-design/icons";
import { getMovieById, updateMovie } from "../../../service/movie/index";
import { getShowtimes, deleteShowtime } from "../../../service/showtime";
import { toast } from "react-toastify";
import dayjs from "dayjs";
import EditShowTime from "../ShowTime/EditShowTime";

const { TextArea } = Input;
const { Text } = Typography;

const genreOptions = [
   { value: "Hành động", label: "Phim Hành Động (Action)" },
  { value: "Kinh dị", label: "Phim Kinh Dị (Horror)" },
  { value: "Tình cảm", label: "Phim Tình Cảm (Romance)" },
  { value: "Hài", label: "Phim Hài (Comedy)" },
  { value: "Khoa học viễn tưởng", label: "Phim Khoa Học Viễn Tưởng (Science Fiction)" },
  { value: "Hành trình", label: "Phim Hành Trình (Adventure)" },
  { value: "Cổ trang", label: "Phim Cổ Trang (Historical)" },
  { value: "Tâm lý", label: "Phim Tâm Lý (Psychological Thriller)" },
  { value: "Hoạt hình", label: "Phim Hoạt Hình (Animation)" },
  { value: "Khoa học", label: "Phim Khoa Học (Documentary)" },
  { value: "Viễn tưởng", label: "Phim Viễn Tưởng (Fantasy)" },
  { value: "Tội phạm", label: "Phim Tội Phạm (Crime)" },
  { value: "Lãng mạn - hài", label: "Phim Lãng Mạn - Tình Cảm (Romantic Comedy)" },
  { value: "Gia đình", label: "Phim Gia Đình (Family)" },
  { value: "Chính kịch", label: "Phim Chính Kịch (Drama)" },
  { value: "Chiến tranh", label: "Phim Chiến Tranh (War)" },
  { value: "Hồi ký", label: "Phim Hồi Ký (Biography)" },
  { value: "Nhạc kịch", label: "Phim Musicals" },
  { value: "Thể loại khác", label: "Thể loại khác" },
];

const languageOptions = [
  { value: "Tiếng việt", label: "Tiếng Việt" },
  { value: "Tiếng anh", label: "Tiếng Anh" },
  { value: "Tiếng trung", label: "Tiếng Trung" },
  { value: "Tiếng nhật", label: "Tiếng Nhật" },
  { value: "Tiếng hàn", label: "Tiếng Hàn" },
  { value: "Tiếng pháp", label: "Tiếng Pháp" },
  { value: "Tiếng Đức", label: "Tiếng Đức" },
  { value: "Tiếng Nga", label: "Tiếng Nga" },
  { value: "Ngôn ngữ khác", label: "Ngôn ngữ khác" },
];

const versionOptions = [
  { value: "2D", label: "2D" },
  { value: "3D", label: "3D" },
  { value: "IMAX", label: "IMAX" },
  { value: "4DX", label: "4DX" },
];

const ageRatingOptions = [
  { value: "P", label: "P - Mọi lứa tuổi" },
  { value: "13", label: "C13 - Trên 13 tuổi" },
  { value: "16", label: "C16 - Trên 16 tuổi" },
  { value: "18", label: "C18 - Trên 18 tuổi" },
];

const EditMovie = ({ visible, onCancel, onSuccess, movieID }) => {
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(true);
  const [posterPreview, setPosterPreview] = useState(null);
  const [trailerUrl, setTrailerUrl] = useState("");
  const [originPosterUrl, setOriginPosterUrl] = useState("");
  const [showtimesLoading, setShowtimesLoading] = useState(false);
  const [movieShowtimes, setMovieShowtimes] = useState([]);
  const [deletingShowtimeId, setDeletingShowtimeId] = useState(null);

  const flattenMovieShowtimes = (data, targetMovieId) => {
    const normalizedMovieId = Number(targetMovieId);
    const result = [];

    data.forEach((city) => {
      city.cinemas?.forEach((cinema) => {
        cinema.cinemaRooms?.forEach((room) => {
          room.showtimes?.forEach((show) => {
            show.times?.forEach((time) => {
              if (Number(time.movieId) !== normalizedMovieId) return;

              result.push({
                id: time.showtimeID,
                showtimeId: time.showtimeID,
                movieId: Number(time.movieId),
                movieTitle: time.movieTitle,
                version: time.version,
                active: Boolean(time.active),
                cityName: city.cityName,
                cinemaID: cinema.cinemaID,
                cinemaName: cinema.name,
                cinemaRoomId: room.cinemaRoomID,
                cinemaRoom: room.roomName,
                date: show.date,
                time: time.time,
                toTime: time.toTime,
              });
            });
          });
        });
      });
    });

    return result.sort((a, b) => {
      const left = dayjs(`${a.date} ${String(a.time).slice(0, 5)}`);
      const right = dayjs(`${b.date} ${String(b.time).slice(0, 5)}`);
      return right.valueOf() - left.valueOf();
    });
  };

  const loadMovieShowtimes = async (targetMovieId = movieID) => {
    if (!targetMovieId) return;

    setShowtimesLoading(true);
    try {
      const response = await getShowtimes();
      if (!response.error) {
        setMovieShowtimes(flattenMovieShowtimes(response.result || [], targetMovieId));
      } else {
        toast.error(response.message || "Không thể lấy danh sách suất chiếu của phim");
      }
    } catch (error) {
      toast.error("Không thể lấy danh sách suất chiếu của phim");
    } finally {
      setShowtimesLoading(false);
    }
  };

  useEffect(() => {
    if (visible && movieID) {
      setFetching(true);
      loadMovieShowtimes(movieID);
      getMovieById(movieID).then((res) => {
        if (!res.error) {
          const movie = res.result;
          setOriginPosterUrl(movie.poster);
          setPosterPreview(movie.poster);
          setTrailerUrl(movie.trailer || "");
          form.setFieldsValue({
            ...movie,
            releaseDate: movie.releaseDate ? dayjs(movie.releaseDate) : null,
            // Đảm bảo poster là mảng file object cho Upload
            poster: movie.poster
              ? [
                  {
                    uid: "-1",
                    name: "poster.jpg",
                    status: "done",
                    url: movie.poster,
                  },
                ]
              : [],
          });
        }
        setFetching(false);
      });
    }
  }, [visible, movieID, form]);

  useEffect(() => {
    if (!visible) {
      setMovieShowtimes([]);
      setDeletingShowtimeId(null);
    }
  }, [visible]);

  const normFile = (e) => {
    if (Array.isArray(e)) return e;
    return e?.fileList;
  };

  const onPosterChange = (info) => {
    const file = info.file?.originFileObj;
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => setPosterPreview(e.target.result);
      reader.readAsDataURL(file);
    } else if (info.file?.url) {
      setPosterPreview(info.file.url);
    } else {
      setPosterPreview(originPosterUrl);
    }
  };

  const getYoutubeEmbedUrl = (url) => {
    if (!url) return "";
    const match = url.match(
      /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/)([\w-]{11})/
    );
    return match ? `https://www.youtube.com/embed/${match[1]}` : "";
  };

  const uploadToCloudinary = async (file) => {
    const CLOUDINARY_UPLOAD_PRESET = "phuocnt-cloudinary";
    const CLOUDINARY_CLOUD_NAME = "dl5dphe0f";
    const formData = new FormData();
    formData.append("file", file);
    formData.append("upload_preset", CLOUDINARY_UPLOAD_PRESET);

    const response = await fetch(
      `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`,
      {
        method: "POST",
        body: formData,
      }
    );
    const data = await response.json();
    return data.secure_url;
  };

  const onFinish = async (values) => {
    try {
      setLoading(true);
      let newPosterUrl = originPosterUrl;
      const file = values.poster?.[0]?.originFileObj;
      if (file) {
        newPosterUrl = await uploadToCloudinary(file);
      } else if (values.posterUrl) {
        newPosterUrl = values.posterUrl;
      }

      const releaseDate = values.releaseDate
        ? dayjs(values.releaseDate).format("YYYY-MM-DD")
        : "";

      const movieData = {
        title: values.title,
        actors: values.actors,
        director: values.director,
        productionCompany: values.productionCompany,
        runningTime: values.runningTime,
        version: values.version,
        trailer: values.trailer,
        content: values.content,
        genre: Array.isArray(values.genre) ? values.genre.join(",") : values.genre,
        language: Array.isArray(values.language) ? values.language.join(",") : values.language,
        ageRating: values.ageRating,
        releaseDate,
        poster: newPosterUrl,
      };

      const response = await updateMovie(movieID, movieData);
      if (!response.error) {
        toast.success(response.message || "Cập nhật phim thành công!");
        onSuccess && onSuccess();
        onCancel && onCancel();
      } else {
        toast.error(response.message || "Cập nhật phim thất bại");
      }
    } catch (error) {
      toast.error("Cập nhật phim thất bại");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteShowtime = async (showtimeId) => {
    try {
      setDeletingShowtimeId(showtimeId);
      const response = await deleteShowtime(showtimeId);

      if (!response.error && (response.status === 200 || response.status === 204)) {
        if (response.result?.failures?.length) {
          response.result.failures.forEach((failure) => toast.error(failure));
        } else {
          toast.success("Xóa suất chiếu thành công!");
          await loadMovieShowtimes(movieID);
        }
        return;
      }

      toast.error(response.message || "Xóa suất chiếu thất bại");
    } catch (error) {
      toast.error("Xóa suất chiếu thất bại");
    } finally {
      setDeletingShowtimeId(null);
    }
  };

  const showtimeColumns = [
    {
      title: "Ngày chiếu",
      dataIndex: "date",
      key: "date",
      width: 130,
      render: (value) => (
        <Space size={6}>
          <CalendarOutlined className="text-blue-600" />
          <span>{value ? dayjs(value).format("DD/MM/YYYY") : "-"}</span>
        </Space>
      ),
    },
    {
      title: "Giờ chiếu",
      key: "timeRange",
      width: 150,
      render: (_, record) => (
        <Space size={6}>
          <ClockCircleOutlined className="text-indigo-600" />
          <span>
            {record.time?.slice(0, 5)} - {record.toTime?.slice(0, 5)}
          </span>
        </Space>
      ),
    },
    {
      title: "Rạp / Phòng",
      key: "cinemaRoom",
      render: (_, record) => (
        <div>
          <div className="font-medium text-gray-900">{record.cinemaName}</div>
          <div className="text-xs text-gray-500">{record.cityName} • {record.cinemaRoom}</div>
        </div>
      ),
    },
    {
      title: "Phiên bản",
      dataIndex: "version",
      key: "version",
      width: 110,
      render: (value) => <Tag color="blue">{value || "-"}</Tag>,
    },
    {
      title: "Trạng thái",
      dataIndex: "active",
      key: "active",
      width: 110,
      render: (active) => (
        <Tag color={active ? "green" : "default"}>{active ? "Đang bật" : "Đã tắt"}</Tag>
      ),
    },
    {
      title: "Thao tác",
      key: "actions",
      width: 170,
      render: (_, record) => (
        <Space wrap>
          <EditShowTime
            showtime={record}
            onSuccess={() => loadMovieShowtimes(movieID)}
            buttonProps={{
              children: "Sửa",
            }}
          />
          <Popconfirm
            title="Xóa suất chiếu"
            description="Bạn có chắc muốn xóa suất chiếu này?"
            okText="Xóa"
            cancelText="Hủy"
            okButtonProps={{ danger: true, loading: deletingShowtimeId === record.showtimeId }}
            onConfirm={() => handleDeleteShowtime(record.showtimeId)}
          >
            <Button
              danger
              size="small"
              icon={<DeleteOutlined />}
              loading={deletingShowtimeId === record.showtimeId}
            >
              Xóa
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <Modal
      open={visible}
      onCancel={onCancel}
      footer={null}
      width={1100}
      title={
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg">
            <VideoCameraOutlined className="text-white" />
          </div>
          <span className="text-xl font-bold text-gray-900">Cập nhật phim</span>
        </div>
      }
      destroyOnHidden
      style={{ top: 30 }}
      className="!rounded-xl"
    >
      {fetching ? (
        <div style={{ textAlign: "center", padding: 40 }}>
          <Spin size="large" />
        </div>
      ) : (
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          autoComplete="off"
          className="mt-2"
        >
          <Row gutter={32}>
            {/* Bên trái: Poster & Trailer */}
            <Col xs={24} md={10}>
              <div className="bg-gradient-to-br from-blue-900 to-indigo-700 rounded-xl p-6 shadow-lg flex flex-col items-center min-h-[480px] border border-blue-200">
                <div className="w-full flex flex-col items-center mb-6">
                  <Form.Item
                    name="poster"
                    label={<span className="text-white font-semibold text-lg"> Poster phim (tải từ máy)</span>}
                    valuePropName="fileList"
                    getValueFromEvent={normFile}
                    style={{ marginBottom: 0, width: "100%" }}
                  >
                    <Upload
                      beforeUpload={() => false}
                      maxCount={1}
                      accept="image/*"
                      listType="picture"
                      onChange={onPosterChange}
                      defaultFileList={
                        originPosterUrl
                          ? [
                              {
                                uid: "-1",
                                name: "poster.jpg",
                                status: "done",
                                url: originPosterUrl,
                              },
                            ]
                          : []
                      }
                    >
                      <Button 
                        icon={<UploadOutlined />}
                        className="bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white border-0 shadow-lg hover:shadow-xl transition-all duration-300"
                      >
                         Chọn ảnh
                      </Button>
                    </Upload>
                  </Form.Item>
                  <Form.Item
                    name="posterUrl"
                    label={<span className="text-white font-semibold text-lg"> Hoặc nhập URL poster</span>}
                    style={{ width: "100%", marginTop: 8 }}
                  >
                    <Input
                      prefix={<PictureOutlined className="text-blue-400" />}
                      placeholder="Dán URL poster tại đây nếu không tải ảnh"
                      onChange={e => setPosterPreview(e.target.value || null)}
                      onBlur={e => setPosterPreview(e.target.value || null)}
                      className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                    />
                  </Form.Item>
                  {posterPreview && (
                    <div className="w-full flex justify-center mt-2">
                      <img
                        src={posterPreview}
                        alt="Poster Preview"
                        style={{
                          maxWidth: 220,
                          maxHeight: 320,
                          borderRadius: 12,
                          boxShadow: "0 4px 20px rgba(0,0,0,0.3)",
                          background: "#fff",
                          objectFit: "cover",
                          border: "3px solid white"
                        }}
                        onError={e => (e.target.style.display = "none")}
                      />
                    </div>
                  )}
                </div>
                <Divider className="bg-blue-300" />
                <div className="w-full">
                  <Form.Item
                    name="trailer"
                    label={<span className="text-white font-semibold text-lg"> Trailer (URL)</span>}
                    rules={[{ required: true, message: "Vui lòng nhập link trailer" }]}
                    style={{ marginBottom: 8 }}
                  >
                    <Input
                      prefix={<VideoCameraOutlined className="text-blue-400" />}
                      placeholder="Nhập link trailer"
                      value={trailerUrl}
                      onChange={e => setTrailerUrl(e.target.value)}
                      className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                    />
                  </Form.Item>
                  <div className="w-full h-72 bg-gradient-to-br from-gray-900 to-black rounded-xl flex items-center justify-center mt-2 border border-blue-300 shadow-lg">
                    {getYoutubeEmbedUrl(trailerUrl) ? (
                      <iframe
                        width="100%"
                        height="100%"
                        src={getYoutubeEmbedUrl(trailerUrl)}
                        title="YouTube trailer"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        allowFullScreen
                        style={{ border: 0, borderRadius: 8, width: "100%", height: "100%" }}
                      />
                    ) : (
                      <div className="text-center">
                        <VideoCameraOutlined className="text-4xl text-blue-400 mb-2" />
                        <span className="text-white text-sm opacity-80"> Xem trước trailer</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </Col>
            {/* Bên phải: Thông tin phim */}
            <Col xs={24} md={14}>
              <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl shadow-lg p-6 border border-blue-200">
                <Form.Item
                  name="title"
                  label={<span className="font-semibold text-gray-900 text-lg"> Tên phim</span>}
                  rules={[{ required: true, message: "Vui lòng nhập tên phim" }]}
                >
                  <Input 
                    placeholder="Nhập tên phim" 
                    className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                  />
                </Form.Item>
                <Form.Item
                  name="content"
                  label={<span className="font-semibold text-gray-900 text-lg"> Nội dung</span>}
                  rules={[{ required: true, message: "Vui lòng nhập nội dung phim" }]}
                >
                  <TextArea 
                    rows={3} 
                    placeholder="Nhập nội dung phim" 
                    className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                  />
                </Form.Item>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="productionCompany"
                      label={<span className="font-semibold text-gray-900"> Hãng sản xuất</span>}
                      rules={[{ required: true, message: "Vui lòng nhập hãng sản xuất" }]}
                    >
                      <Input 
                        placeholder="Nhập hãng sản xuất" 
                        className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="director"
                      label={<span className="font-semibold text-gray-900"> Đạo diễn</span>}
                      rules={[{ required: true, message: "Vui lòng nhập đạo diễn" }]}
                    >
                      <Input 
                        placeholder="Nhập tên đạo diễn" 
                        className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Form.Item
                  name="actors"
                  label={<span className="font-semibold text-gray-900"> Diễn viên</span>}
                  rules={[{ required: true, message: "Vui lòng nhập diễn viên" }]}
                >
                  <Input 
                    placeholder="Nhập tên diễn viên, cách nhau bởi dấu phẩy" 
                    className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                  />
                </Form.Item>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="genre"
                      label={<span className="font-semibold text-gray-900"> Thể loại</span>}
                      rules={[{ required: true, message: "Vui lòng chọn thể loại" }]}
                    >
                      <Select
                        mode="multiple"
                        placeholder="Chọn thể loại"
                        options={genreOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="language"
                      label={<span className="font-semibold text-gray-900"> Ngôn ngữ</span>}
                      rules={[{ required: true, message: "Vui lòng chọn ngôn ngữ" }]}
                    >
                      <Select
                        mode="multiple"
                        placeholder="Chọn ngôn ngữ"
                        options={languageOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="version"
                      label={<span className="font-semibold text-gray-900"> Phiên bản</span>}
                      rules={[{ required: true, message: "Vui lòng chọn phiên bản" }]}
                    >
                      <Select
                        placeholder="Chọn phiên bản"
                        options={versionOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="ageRating"
                      label={<span className="font-semibold text-gray-900"> Giới hạn tuổi</span>}
                      rules={[{ required: true, message: "Vui lòng chọn giới hạn tuổi" }]}
                    >
                      <Select
                        placeholder="Chọn giới hạn tuổi"
                        options={ageRatingOptions}
                        allowClear
                        className="rounded-lg"
                      />
                    </Form.Item>
                  </Col>
                </Row>
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item
                      name="runningTime"
                      label={<span className="font-semibold text-gray-900">⏰ Thời lượng phim</span>}
                      rules={[{ required: true, message: "Vui lòng nhập thời lượng" }]}
                    >
                      <Input
                        type="number"
                        min={1}
                        placeholder="VD: 120 phút"
                        className="rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
                      />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item
                      name="releaseDate"
                      label={<span className="font-semibold text-gray-900"> Ngày ra mắt</span>}
                      rules={[{ required: true, message: "Vui lòng chọn ngày ra mắt" }]}
                    >
                      <DatePicker 
                        className="w-full rounded-lg border-gray-300 focus:border-blue-500 focus:ring-2 focus:ring-blue-500" 
                        format="YYYY-MM-DD" 
                      />
                    </Form.Item>
                  </Col>
                </Row>
              </div>
            </Col>
          </Row>
          <Divider orientation="left" className="!mt-8">
            Suất chiếu hiện có của phim
          </Divider>
          <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-xl border border-blue-100 p-4 shadow-sm">
            <div className="flex flex-col gap-1 mb-4">
              <Text strong className="text-base text-gray-900">
                Quản lý suất chiếu trong mục chỉnh sửa phim
              </Text>
              <Text type="secondary">
                Danh sách được sắp xếp từ suất chiếu mới nhất đến cũ nhất.
              </Text>
            </div>

            <Table
              rowKey="showtimeId"
              loading={showtimesLoading}
              columns={showtimeColumns}
              dataSource={movieShowtimes}
              pagination={{ pageSize: 5, hideOnSinglePage: true }}
              locale={{
                emptyText: (
                  <Empty
                    description="Phim này chưa có suất chiếu nào"
                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                  />
                ),
              }}
              scroll={{ x: 900 }}
              size="middle"
            />
          </div>
          <Divider className="my-4" />
          <div className="flex gap-3 justify-end">
            <Button 
              onClick={onCancel} 
              disabled={loading} 
              className="border-gray-300 text-gray-700 hover:border-gray-400 hover:text-gray-800"
            >
              Hủy
            </Button>
            <Button 
              type="primary" 
              htmlType="submit" 
              loading={loading}
              className="bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 border-0 shadow-lg"
            >
              Cập nhật phim
            </Button>
          </div>
        </Form>
      )}
    </Modal>
  );
};

export default EditMovie;

import React, { useEffect, useState } from "react";
import { EditOutlined, HomeOutlined, VideoCameraOutlined } from "@ant-design/icons";
import { Modal, Button, Form, Select, DatePicker, TimePicker, message, Row, Col, Input } from "antd";
import { updateShowtime, fetchAllRooms } from "../../../service/showtime";
import dayjs from "dayjs";
import { useLocation } from "react-router-dom";

const { Option } = Select;

const EditShowTime = ({ showtime, onSuccess }) => {
  const [visible, setVisible] = useState(false);
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);

  const [allRooms, setAllRooms] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [cinemaRooms, setCinemaRooms] = useState([]);

  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const movieIdFromUrl = params.get("movieId");
  // Ưu tiên lấy movieId từ showtime, nếu không có thì lấy từ URL
  let movieIdToUse = showtime.movieId;
  if (!movieIdToUse || movieIdToUse === 0) {
    movieIdToUse = movieIdFromUrl ? Number(movieIdFromUrl) : undefined;
  }

  useEffect(() => {
    const loadRooms = async () => {
      const res = await fetchAllRooms();
      if (!res.error) {
        setAllRooms(res.result);
        setCities(res.result.map(city => ({ id: city.cityID, name: city.name, cinemas: city.cinemas })));
      }
    };
    loadRooms();
  }, []);

  const openModal = () => {
    setVisible(true);
    // Tìm city, cinema, room theo showtime.cinemaRoomId
    let cityID, cinemaID, cinemaRoomID = showtime.cinemaRoomId;
    let cityObj, cinemaObj, roomObj;
    allRooms.forEach(city => {
      city.cinemas.forEach(cinema => {
        cinema.cinemaRooms.forEach(room => {
          if (room.cinemaRoomID === cinemaRoomID) {
            cityID = city.cityID;
            cinemaID = cinema.cinemaID;
            cityObj = city;
            cinemaObj = cinema;
            roomObj = room;
          }
        });
      });
    });
    setCinemas(cityObj ? cityObj.cinemas : []);
    setCinemaRooms(cinemaObj ? cinemaObj.cinemaRooms : []);
    form.setFieldsValue({
      showtimeId: showtime.showtimeId,
      movieId: movieIdToUse || "", // luôn set vào form, tránh undefined
      cityID: cityID,
      cinemaID: cinemaID,
      cinemaRoomId: cinemaRoomID,
      date: showtime.date ? dayjs(showtime.date) : null,
      time: showtime.time ? dayjs(showtime.time, "HH:mm") : null,
      version: showtime.version,
    });
  };

  const handleCityChange = (cityID) => {
    const city = allRooms.find(c => c.cityID === cityID);
    setCinemas(city ? city.cinemas : []);
    setCinemaRooms([]);
    form.setFieldsValue({ cinemaID: undefined, cinemaRoomId: undefined });
  };

  const handleCinemaChange = (cinemaID) => {
    const cinema = cinemas.find(c => c.cinemaID === cinemaID);
    setCinemaRooms(cinema ? cinema.cinemaRooms : []);
    form.setFieldsValue({ cinemaRoomId: undefined });
  };

  const handleOk = async () => {
    try {
      setLoading(true);
      const values = await form.validateFields();
      const payload = {
        showtimeId: values.showtimeId,
        movieId: values.movieId, // lấy trực tiếp từ form
        cinemaRoomId: values.cinemaRoomId,
        date: values.date ? values.date.format("YYYY-MM-DD") : "",
        time: values.time ? values.time.format("HH:mm") : "",
        version: values.version,
      };
      const res = await updateShowtime(payload);
      if (!res.error) {
        message.success("Cập nhật suất chiếu thành công!");
        setVisible(false);
        onSuccess && onSuccess();
      } else {
        message.error(res.message);
      }
    } catch (err) {
      // validation error
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Button
        icon={<EditOutlined />}
        onClick={openModal}
        type="primary"
        size="small"
        style={{ marginRight: 8 }}
      />
      <Modal
        title={
          <span className="text-2xl font-bold text-blue-700 flex items-center gap-2">
            <VideoCameraOutlined /> Chỉnh sửa suất chiếu
          </span>
        }
        open={visible}
        onOk={handleOk}
        onCancel={() => setVisible(false)}
        confirmLoading={loading}
        okText="Lưu"
        cancelText="Hủy"
        width={600}
        styles={{ body: { padding: 24 } }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="showtimeId" label="ID suất chiếu" hidden>
            <Input />
          </Form.Item>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="movieId" label={<span><VideoCameraOutlined /> ID phim</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Input disabled />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="version" label={<span><HomeOutlined /> Phiên bản</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Select placeholder="Chọn phiên bản">
                  <Option value="2D">2D</Option>
                  <Option value="3D">3D</Option>
                  <Option value="IMAX">IMAX</Option>
                  <Option value="4DX">4DX</Option>
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={8}>
              <Form.Item
                name="cityID"
                label="Thành phố"
                rules={[{ required: true, message: "Vui lòng chọn thành phố" }]}
              >
                <Select placeholder="Chọn thành phố" onChange={handleCityChange}>
                  {cities.map(city => (
                    <Option key={city.id} value={city.id}>{city.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaID"
                label="Rạp"
                rules={[{ required: true, message: "Vui lòng chọn rạp" }]}
              >
                <Select placeholder="Chọn rạp" onChange={handleCinemaChange} disabled={!cinemas.length}>
                  {cinemas.map(cinema => (
                    <Option key={cinema.cinemaID} value={cinema.cinemaID}>{cinema.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaRoomId"
                label="Phòng chiếu"
                rules={[{ required: true, message: "Vui lòng chọn phòng chiếu" }]}
              >
                <Select placeholder="Chọn phòng chiếu" disabled={!cinemaRooms.length}>
                  {cinemaRooms.map(room => (
                    <Option key={room.cinemaRoomID} value={room.cinemaRoomID}>{room.roomName}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="date" label="Ngày chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <DatePicker format="YYYY-MM-DD" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="time" label="Giờ chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <TimePicker format="HH:mm" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
          </Row>
        </Form>
      </Modal>
    </>
  );
};

export default EditShowTime;

import React, { useEffect, useState } from "react";
import { EditOutlined, HomeOutlined, VideoCameraOutlined } from "@ant-design/icons";
import { Modal, Button, Form, Select, DatePicker, TimePicker, message, Row, Col, Input } from "antd";
import { updateShowtime, fetchAllRooms } from "../../../service/showtime";
import dayjs from "dayjs";

const { Option } = Select;

const EditShowTime = ({
  showtime,
  onSuccess,
  visible: controlledVisible,
  onCancel,
  hideTrigger = false,
  buttonProps = {},
}) => {
  const [internalVisible, setInternalVisible] = useState(false);
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);

  const [allRooms, setAllRooms] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [cinemaRooms, setCinemaRooms] = useState([]);

  const isControlled = typeof controlledVisible === "boolean";
  const visible = isControlled ? controlledVisible : internalVisible;

  const closeModal = () => {
    if (!isControlled) {
      setInternalVisible(false);
    }
    onCancel?.();
  };

  useEffect(() => {
    const loadRooms = async () => {
      const res = await fetchAllRooms();
      if (!res.error) {
        setAllRooms(res.result);
        setCities(res.result.map(city => ({ id: city.cityID, name: city.name, cinemas: city.cinemas })));
      }
    };
    loadRooms();
  }, []);

  useEffect(() => {
    if (!visible || !showtime || allRooms.length === 0) return;

    const movieIdToUse = showtime.movieId ? Number(showtime.movieId) : undefined;
    let cityID, cinemaID, cinemaRoomID = showtime.cinemaRoomId;
    let cityObj, cinemaObj;
    allRooms.forEach(city => {
      city.cinemas.forEach(cinema => {
        cinema.cinemaRooms.forEach(room => {
          if (room.cinemaRoomID === cinemaRoomID) {
            cityID = city.cityID;
            cinemaID = cinema.cinemaID;
            cityObj = city;
            cinemaObj = cinema;
          }
        });
      });
    });
    setCinemas(cityObj ? cityObj.cinemas : []);
    setCinemaRooms(cinemaObj ? cinemaObj.cinemaRooms : []);
    form.setFieldsValue({
      showtimeId: showtime.showtimeId || showtime.id,
      movieId: movieIdToUse || "", // luôn set vào form, tránh undefined
      cityID: cityID,
      cinemaID: cinemaID,
      cinemaRoomId: cinemaRoomID,
      date: showtime.date ? dayjs(showtime.date) : null,
      time: showtime.time ? dayjs(showtime.time?.slice(0, 5), "HH:mm") : null,
      version: showtime.version,
    });
  }, [visible, showtime, allRooms, form]);

  const openModal = () => {
    if (!isControlled) {
      setInternalVisible(true);
    }
  };

  const handleCityChange = (cityID) => {
    const city = allRooms.find(c => c.cityID === cityID);
    setCinemas(city ? city.cinemas : []);
    setCinemaRooms([]);
    form.setFieldsValue({ cinemaID: undefined, cinemaRoomId: undefined });
  };

  const handleCinemaChange = (cinemaID) => {
    const cinema = cinemas.find(c => c.cinemaID === cinemaID);
    setCinemaRooms(cinema ? cinema.cinemaRooms : []);
    form.setFieldsValue({ cinemaRoomId: undefined });
  };

  const handleOk = async () => {
    try {
      setLoading(true);
      const values = await form.validateFields();
      const payload = {
        showtimeId: values.showtimeId,
        movieId: values.movieId, // lấy trực tiếp từ form
        cinemaRoomId: values.cinemaRoomId,
        date: values.date ? values.date.format("YYYY-MM-DD") : "",
        time: values.time ? values.time.format("HH:mm") : "",
        version: values.version,
      };
      const res = await updateShowtime(payload);
      if (!res.error) {
        message.success("Cập nhật suất chiếu thành công!");
        closeModal();
        onSuccess && onSuccess();
      } else {
        message.error(res.message);
      }
    } catch (err) {
      // validation error
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      {!hideTrigger && (
        <Button
          icon={<EditOutlined />}
          onClick={openModal}
          type="primary"
          size="small"
          style={{ marginRight: 8 }}
          {...buttonProps}
        />
      )}
      <Modal
        title={
          <span className="text-2xl font-bold text-blue-700 flex items-center gap-2">
            <VideoCameraOutlined /> Chỉnh sửa suất chiếu
          </span>
        }
        open={visible}
        onOk={handleOk}
        onCancel={closeModal}
        confirmLoading={loading}
        okText="Lưu"
        cancelText="Hủy"
        width={600}
        styles={{ body: { padding: 24 } }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="showtimeId" label="ID suất chiếu" hidden>
            <Input />
          </Form.Item>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="movieId" label={<span><VideoCameraOutlined /> ID phim</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Input disabled />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="version" label={<span><HomeOutlined /> Phiên bản</span>} rules={[{ required: true, message: "Bắt buộc" }]}>
                <Select placeholder="Chọn phiên bản">
                  <Option value="2D">2D</Option>
                  <Option value="3D">3D</Option>
                  <Option value="IMAX">IMAX</Option>
                  <Option value="4DX">4DX</Option>
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={8}>
              <Form.Item
                name="cityID"
                label="Thành phố"
                rules={[{ required: true, message: "Vui lòng chọn thành phố" }]}
              >
                <Select placeholder="Chọn thành phố" onChange={handleCityChange}>
                  {cities.map(city => (
                    <Option key={city.id} value={city.id}>{city.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaID"
                label="Rạp"
                rules={[{ required: true, message: "Vui lòng chọn rạp" }]}
              >
                <Select placeholder="Chọn rạp" onChange={handleCinemaChange} disabled={!cinemas.length}>
                  {cinemas.map(cinema => (
                    <Option key={cinema.cinemaID} value={cinema.cinemaID}>{cinema.name}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="cinemaRoomId"
                label="Phòng chiếu"
                rules={[{ required: true, message: "Vui lòng chọn phòng chiếu" }]}
              >
                <Select placeholder="Chọn phòng chiếu" disabled={!cinemaRooms.length}>
                  {cinemaRooms.map(room => (
                    <Option key={room.cinemaRoomID} value={room.cinemaRoomID}>{room.roomName}</Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item name="date" label="Ngày chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <DatePicker format="YYYY-MM-DD" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item name="time" label="Giờ chiếu" rules={[{ required: true, message: "Bắt buộc" }]}>
                <TimePicker format="HH:mm" style={{ width: "100%" }} />
              </Form.Item>
            </Col>
          </Row>
        </Form>
      </Modal>
    </>
  );
};

export default EditShowTime;

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom"; // Thêm dòng này
import { getShowtimesByMovie } from "../../../service/bookmovieticket";
import BookSeat from "./BookSeat";
import ConfirmBooking from "./ConfirmBooking";
import { FiLogIn } from "react-icons/fi";
import { MdEventBusy } from "react-icons/md";
import Snackbar from "./Snackbar"; // Import Snackbar

const BookMovieTicket = ({ movieId, movieTitle, poster, quickBooking, bookingInfo, setBookingInfo, onShowtimeChange, selectedFoods, setSelectedFoods }) => {
  const [showtimes, setShowtimes] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [dates, setDates] = useState([]);
  const [times, setTimes] = useState([]);
  const [selected, setSelected] = useState({
    city: "",
    cinema: "",
    room: "",
    date: "",
    time: "",
    showtime: null,
  });
  const [availableSeats, setAvailableSeats] = useState([]);
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [step, setStep] = useState(1);
  const [confirmInfo, setConfirmInfo] = useState(null);
  const [successInfo, setSuccessInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [apiMessage, setApiMessage] = useState("");
  const [error, setError] = useState("");
  const [showRoomDropdown, setShowRoomDropdown] = useState(true);
  const [selectedDate, setSelectedDate] = useState(""); // Thêm state này
  const navigate = useNavigate(); // Thêm dòng này

  // Lấy dữ liệu suất chiếu và flatten
  useEffect(() => {
    const fetchShowtimes = async () => {
      setLoading(true);
      try {
        const res = await getShowtimesByMovie(movieId);
        const result = res.data.result;
        let flatShowtimes = [];
        if (result && result.dates) {
          result.dates.forEach(dateObj => {
            const showDate = dateObj.date;
            dateObj.cities.forEach(city => {
              const cityName = city.name;
              city.cinemas.forEach(cinema => {
                const cinemaName = cinema.name;
                cinema.cinemaRooms.forEach(room => {
                  const cinemaRoomName = room.roomName;
                  const cinemaRoomId = room.cinemaRoomID || room.cinemaRoomId;
                  // Lọc chỉ times active
                  room.times
                    .filter(time => time.active)
                    .forEach(time => {
                      flatShowtimes.push({
                        cityName,
                        cinemaName,
                        cinemaRoomName,
                        cinemaRoomId,
                        showDate,
                        showTime: time.time,
                        seats: time.seats,
                      });
                    });
                });
              });
            });
          });
        }
        setShowtimes(flatShowtimes);
        setCities([...new Set(flatShowtimes.map((s) => s.cityName))]);
      } catch {
        setError("Đăng nhập để đặt vé.");
      }
      setLoading(false);
    };
    fetchShowtimes();
  }, [movieId]);

  // Dropdown logic
  useEffect(() => {
    if (!selected.city) {
      setCinemas([]);
      setSelected(prev => ({ ...prev, cinema: "", date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(s => s.cityName === selected.city);
    setCinemas([...new Set(filtered.map(s => s.cinemaName))]);
    // Không reset cinema nếu đã chọn
  }, [selected.city, showtimes]);

  // Khi chọn rạp, chỉ reset ngày, giờ, phòng, showtime
  useEffect(() => {
    if (!selected.cinema) {
      setDates([]);
      setSelected(prev => ({ ...prev, date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s => s.cityName === selected.city && s.cinemaName === selected.cinema
    );
    setDates([...new Set(filtered.map(s => s.showDate))]);
    // Không reset cinema ở đây nữa
  }, [selected.cinema, selected.city, showtimes]);

  // Khi chọn ngày, chỉ reset giờ, phòng, showtime
  useEffect(() => {
    if (!selected.date) {
      setTimes([]);
      setSelected(prev => ({ ...prev, time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date
    );
    setTimes([...new Set(filtered.map(s => s.showTime))]);
    // Không reset date ở đây nữa
  }, [selected.date, selected.cinema, selected.city, showtimes]);

  // Khi chọn giờ, chỉ reset phòng, showtime
  useEffect(() => {
    if (!selected.time) {
      setShowRoomDropdown(true);
      setRooms([]);
      setSelected(prev => ({ ...prev, room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date &&
        s.showTime === selected.time
    );
    const uniqueRooms = [...new Set(filtered.map(s => s.cinemaRoomName))];
    setRooms(uniqueRooms);

    if (uniqueRooms.length === 1) {
      setShowRoomDropdown(false);
      setSelected(prev => ({
        ...prev,
        room: uniqueRooms[0],
        showtime: filtered.find(s => s.cinemaRoomName === uniqueRooms[0]),
      }));
      setAvailableSeats(filtered[0]?.seats || []);
      setSelectedSeats([]);
    } else {
      setShowRoomDropdown(true);
      setSelected(prev => ({ ...prev, room: "", showtime: null }));
      setAvailableSeats([]);
      setSelectedSeats([]);
    }
  }, [selected.time, selected.date, selected.cinema, selected.city, showtimes]);

  useEffect(() => {
    if (!showRoomDropdown || !selected.room) return;
    const showtime = showtimes.find(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date &&
        s.showTime === selected.time &&
        s.cinemaRoomName === selected.room
    );
    setSelected(prev => ({ ...prev, showtime }));
    setAvailableSeats(showtime ? showtime.seats : []);
    setSelectedSeats([]);
  }, [selected.room, showRoomDropdown, selected.city, selected.cinema, selected.date, selected.time, showtimes]);

  // Chọn ghế
  const handleSelectSeat = seat => {
    if (seat.status === "sold" || seat.isAvailable === false) return;
    setSelectedSeats(prev =>
      prev.some(s => s.seatID === seat.seatID)
        ? prev.filter(s => s.seatID !== seat.seatID)
        : [...prev, seat]
    );
    setError("");
  };

  // Khi có quickBooking, tự động set các dropdown
  useEffect(() => {
    if (
      quickBooking &&
      quickBooking.city &&
      quickBooking.cinema &&
      quickBooking.date &&
      quickBooking.time
    ) {
      setSelected(prev => ({
        ...prev,
        city: quickBooking.city,
        cinema: quickBooking.cinema,
        date: quickBooking.date,
        time: quickBooking.time,
      }));
      setSelectedDate(quickBooking.date); // Nếu bạn dùng selectedDate cho UI ngày

      // Nếu có showtime từ quickBooking, sử dụng nó
      if (quickBooking.showtime) {
        setSelected(prev => ({
          ...prev,
          showtime: quickBooking.showtime,
          room: quickBooking.showtime.cinemaRoomName,
        }));
        setAvailableSeats(quickBooking.showtime.seats || []);
        setSelectedSeats([]);
      }
    }
  }, [quickBooking, showtimes]);

  // Cập nhật thông tin booking khi chọn thành phố, rạp, ngày, giờ
  useEffect(() => {
    setBookingInfo(prev => ({
      ...prev,
      movieTitle,
      cityName: selected.city,
      cinemaName: selected.cinema,
      date: selected.date,
      time: selected.time,
    }));
  }, [selected.city, selected.cinema, selected.date, selected.time, movieTitle, setBookingInfo]);

  // Cập nhật khi chọn ghế
  useEffect(() => {
    const totalPrice = selectedSeats.reduce((sum, seat) => sum + (seat.price || 75000), 0);
    setBookingInfo(prev => ({
      ...prev,
      selectedSeats,
      totalPrice,
    }));
  }, [selectedSeats, setBookingInfo]);

  // Đồng bộ selectedFoods vào bookingInfo
  useEffect(() => {
    setBookingInfo(prev => ({
      ...prev,
      selectedFoods,
    }));
  }, [selectedFoods, setBookingInfo]);

  // Cập nhật khi showtime thay đổi
  useEffect(() => {
    if (onShowtimeChange && selected.showtime) {
      onShowtimeChange(selected.showtime);
    }
  }, [selected.showtime, onShowtimeChange]);

  // UI
  if (loading) return <div className="text-center py-4 text-orange-500 font-semibold">Đang tải...</div>;

  if (error === "Đăng nhập để đặt vé.") {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <FiLogIn size={38} />
        <span className="drop-shadow">ĐĂNG NHẬP ĐỂ ĐẶT VÉ</span>
      </div>
    );
  }
  if (error === "Vui lòng đăng nhập để đặt vé!") {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <FiLogIn size={38} />
        <span className="drop-shadow">VUI LÒNG ĐĂNG NHẬP ĐỂ ĐẶT VÉ!</span>
      </div>
    );
  } else if (error) {
    return <div className="text-orange-500 text-center mt-2 font-semibold">{error}</div>;
  }

  // THÊM ĐOẠN NÀY để xử lý trường hợp không có suất chiếu
  if (step === 1 && showtimes.length === 0) {
    return (
      <div className="flex items-center justify-center gap-2 text-orange-500 font-extrabold text-xl text-center drop-shadow-lg animate-pulse">
        <MdEventBusy size={38} />
        <span className="drop-shadow">HIỆN CHƯA CÓ LỊCH CHIẾU</span>
      </div>
    );
  }

  if (step === 1)
    return (
      <div className="flex justify-center items-center bg-transparent py-6" style={{ fontSize: "80%" }}>
        <div className="w-full">
          <h2 className="font-bold text-2xl mb-3 text-orange-500 text-center tracking-wide drop-shadow-lg uppercase">LỊCH CHIẾU</h2>
          {/* Thành phố */}
          <div className="mb-4 flex justify-center items-center gap-2">
            <select
              className="px-3 py-1.5 rounded-lg border border-orange-400 focus:border-orange-600 focus:outline-none min-w-[110px] text-gray-900 font-bold bg-white shadow transition text-sm"
              value={selected.city}
              onChange={e => {
                setSelected(prev => ({ ...prev, city: e.target.value, cinema: "", date: "", time: "", room: "", showtime: null }));
                setSelectedDate("");
              }}
            >
              <option value="">-- Chọn thành phố --</option>
              {cities.map(city => (
                <option key={city} className="text-sm">{city}</option>
              ))}
            </select>
          </div>

          {/* Chọn ngày */}
          {selected.city && (() => {
            const showtimesOfCity = showtimes.filter(s => s.cityName === selected.city);
            const allDates = [...new Set(showtimesOfCity.map(s => s.showDate))];
            if (allDates.length === 0) return null;
            return (
              <div className="mb-4 flex gap-2 justify-center">
                {allDates.map(date => (
                  <button
                    key={date}
                    className={`px-4 py-1.5 rounded-lg font-bold border shadow transition-all duration-200 text-sm
                      ${selectedDate === date
                        ? "bg-gradient-to-r from-orange-400 to-orange-500 text-white border-orange-600 scale-105"
                        : "bg-white text-orange-700 border-orange-400 hover:bg-orange-50 hover:scale-105"}`}
                    onClick={() => {
                      setSelectedDate(date);
                      setSelected(prev => ({ ...prev, date, cinema: "", time: "", room: "", showtime: null }));
                    }}
                  >
                    {date}
                  </button>
                ))}
              </div>
            );
          })()}

          {/* Danh sách rạp, giờ */}
          {selected.city && selectedDate && (
            <div>
              <h3 className="font-bold text-sm mb-2 text-orange-700 text-center tracking-wide uppercase">
                DANH SÁCH RẠP
              </h3>
              {cinemas.length === 0 && (
                <div className="text-gray-400 italic text-center">Không có rạp nào trong thành phố này.</div>
              )}
              {cinemas.map(cinemaName => {
                const showtimesOfCinema = showtimes.filter(
                  s => s.cityName === selected.city && s.cinemaName === cinemaName && s.showDate === selectedDate
                );
                if (showtimesOfCinema.length === 0) return null;
                const timesOfDate = [...new Set(showtimesOfCinema.map(s => s.showTime))];
                return (
                  <div key={cinemaName} className="mb-4 bg-gradient-to-r from-gray-100 to-gray-200 rounded-xl p-3 shadow-inner border border-gray-200">
                    <div className="font-bold text-sm text-orange-700 mb-1 text-center uppercase tracking-wide">{cinemaName}</div>
                    {timesOfDate.length === 0 ? (
                      <div className="text-gray-400 italic text-center">Hiện chưa có lịch chiếu</div>
                    ) : (
                      <div className="flex flex-wrap gap-2 justify-center">
                        {timesOfDate.map(time => {
                          const showtimeObj = showtimesOfCinema.find(s => s.showTime === time);
                          const isSelected = selected.time === time && selected.cinema === cinemaName;
                          return (
                            <button
                              key={time}
                              className={`px-4 py-1.5 rounded-lg font-bold border shadow transition-all duration-200 text-sm
                                ${isSelected
                                  ? "bg-gradient-to-r from-orange-400 to-orange-500 text-white border-orange-600 scale-105"
                                  : "bg-white text-orange-700 border-orange-400 hover:bg-orange-50 hover:scale-105"}`}
                              onClick={() => {
                                setSelected(prev => ({
                                  ...prev,
                                  city: prev.city,
                                  cinema: cinemaName,
                                  date: selectedDate,
                                  time,
                                  room: showtimeObj.cinemaRoomName,
                                  showtime: showtimeObj,
                                }));
                                setAvailableSeats(showtimeObj.seats || []);
                                setSelectedSeats([]);
                              }}
                            >
                              {time}
                            </button>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {/* Hiển thị chọn ghế nếu đã chọn đủ thành phố, ngày, rạp, giờ */}
          {selected.city && selected.cinema && selected.date && selected.time && selected.showtime && (
            <div className="mt-6 transition-all duration-500">
              <BookSeat
                movie={movieTitle}
                availableSeats={availableSeats}
                selectedSeats={selectedSeats}
                handleSelectSeat={handleSelectSeat}
                handleBack={() => {}}
                setBookingInfo={setBookingInfo}
                bookingInfo={bookingInfo}
                selectedFoods={selectedFoods}
                setSelectedFoods={setSelectedFoods}
              />
            </div>
          )}
        </div>
      </div>
    );

  // Bước 2: Chọn ghế
  if (step === 2)
    return (
      <BookSeat
        movie={movieTitle}
        availableSeats={availableSeats}
        selectedSeats={selectedSeats}
        handleSelectSeat={handleSelectSeat}
        handleBack={() => setStep(1)}
        selectedFoods={selectedFoods}
        setSelectedFoods={setSelectedFoods}
      />
    );

  if (step === 3)
    return (
      <div className="text-center py-8">
        <h2 className="text-2xl font-bold text-orange-600 mb-4 drop-shadow-lg">Đặt vé thành công!</h2>
        <pre className="bg-gray-100 rounded p-4 text-left inline-block text-gray-800">{JSON.stringify(successInfo, null, 2)}</pre>
      </div>
    );

  return (
    <>
      {/* ...UI các bước chọn... */}
      {/* Chỉ hiển thị Snackbar khi đã chọn giờ và có đủ thông tin */}
      {selected.time && (
        <Snackbar
          movieId={movieId}
          movieTitle={bookingInfo.movieTitle}
          cinemaName={bookingInfo.cinemaName}
          cityName={bookingInfo.cityName}
          selectedSeats={bookingInfo.selectedSeats}
          totalPrice={bookingInfo.totalPrice}
          date={bookingInfo.date}
          time={bookingInfo.time}
          showtime={selected.showtime}
          onError={setError}
          disabled={
            !bookingInfo.cityName ||
            !bookingInfo.cinemaName ||
            !bookingInfo.date ||
            !bookingInfo.time ||
            bookingInfo.selectedSeats.length === 0
          }
          selectedFoods={selectedFoods}
        />
      )}
    </>
  );
};

export default BookMovieTicket;

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom"; // Thêm dòng này
import { getShowtimesByMovie } from "../../../service/bookmovieticket";
import BookSeat from "./BookSeat";
import ConfirmBooking from "./ConfirmBooking";
import { FiLogIn } from "react-icons/fi";
import { MdEventBusy } from "react-icons/md";
import Snackbar from "./Snackbar"; // Import Snackbar

const BookMovieTicket = ({ movieId, movieTitle, poster, isComingSoon = false, quickBooking, bookingInfo, setBookingInfo, onShowtimeChange, selectedFoods, setSelectedFoods }) => {
  const [showtimes, setShowtimes] = useState([]);
  const [cities, setCities] = useState([]);
  const [cinemas, setCinemas] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [dates, setDates] = useState([]);
  const [times, setTimes] = useState([]);
  const [selected, setSelected] = useState({
    city: "",
    cinema: "",
    room: "",
    date: "",
    time: "",
    showtime: null,
  });
  const [availableSeats, setAvailableSeats] = useState([]);
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [step, setStep] = useState(1);
  const [confirmInfo, setConfirmInfo] = useState(null);
  const [successInfo, setSuccessInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [apiMessage, setApiMessage] = useState("");
  const [error, setError] = useState("");
  const [showRoomDropdown, setShowRoomDropdown] = useState(true);
  const [selectedDate, setSelectedDate] = useState(""); // Thêm state này
  const navigate = useNavigate(); // Thêm dòng này

  // Lấy dữ liệu suất chiếu và flatten
  useEffect(() => {
    const fetchShowtimes = async () => {
      setLoading(true);
      try {
        const res = await getShowtimesByMovie(movieId);
        const result = res.data.result;
        let flatShowtimes = [];
        if (result && result.dates) {
          result.dates.forEach(dateObj => {
            const showDate = dateObj.date;
            dateObj.cities.forEach(city => {
              const cityName = city.name;
              city.cinemas.forEach(cinema => {
                const cinemaName = cinema.name;
                cinema.cinemaRooms.forEach(room => {
                  const cinemaRoomName = room.roomName;
                  const cinemaRoomId = room.cinemaRoomID || room.cinemaRoomId;
                  // Lọc chỉ times active
                  room.times
                    .filter(time => time.active)
                    .forEach(time => {
                      flatShowtimes.push({
                        cityName,
                        cinemaName,
                        cinemaRoomName,
                        cinemaRoomId,
                        showDate,
                        showTime: time.time,
                        seats: time.seats,
                      });
                    });
                });
              });
            });
          });
        }
        setShowtimes(flatShowtimes);
        setCities([...new Set(flatShowtimes.map((s) => s.cityName))]);
      } catch {
        setError("Đăng nhập để đặt vé.");
      }
      setLoading(false);
    };
    fetchShowtimes();
  }, [movieId]);

  // Dropdown logic
  useEffect(() => {
    if (!selected.city) {
      setCinemas([]);
      setSelected(prev => ({ ...prev, cinema: "", date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(s => s.cityName === selected.city);
    setCinemas([...new Set(filtered.map(s => s.cinemaName))]);
    // Không reset cinema nếu đã chọn
  }, [selected.city, showtimes]);

  // Khi chọn rạp, chỉ reset ngày, giờ, phòng, showtime
  useEffect(() => {
    if (!selected.cinema) {
      setDates([]);
      setSelected(prev => ({ ...prev, date: "", time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s => s.cityName === selected.city && s.cinemaName === selected.cinema
    );
    setDates([...new Set(filtered.map(s => s.showDate))]);
    // Không reset cinema ở đây nữa
  }, [selected.cinema, selected.city, showtimes]);

  // Khi chọn ngày, chỉ reset giờ, phòng, showtime
  useEffect(() => {
    if (!selected.date) {
      setTimes([]);
      setSelected(prev => ({ ...prev, time: "", room: "", showtime: null }));
      return;
    }
    const filtered = showtimes.filter(
      s =>
        s.cityName === selected.city &&
        s.cinemaName === selected.cinema &&
        s.showDate === selected.date
    );
    setTimes([...new Set(filtered.map(s => s.showTime))]);
    // Không reset date ở đây nữa
  }, [selected.date, selected.cinema, selected.city, showtimes]);

  // Khi chọn giờ, chỉ reset phòng, showtime
  useEffect(() => {
    if (!selected.time) {
      setShowRoomDropdown(true);
