                    {isFavorite ? <FaHeart /> : <FaRegHeart />}
                  </button>
                </div>
                <div className="flex flex-wrap gap-3 items-center mb-4">
                  <span className="flex items-center gap-2 text-orange-400 text-base font-semibold">
                    <FaTag /> {movie.genre}
                  </span>
                  <span className="flex items-center gap-2 text-orange-400 text-base font-semibold">
                    <FaClock /> {movie.runningTime}’
                  </span>
                  <span className="flex items-center gap-2 text-orange-400 text-base font-semibold">
                    <FaInfoCircle /> {movie.version}
                  </span>
                  <span className="flex items-center gap-2 text-orange-400 text-base font-semibold">
                    <FaClosedCaptioning /> Phụ Đề
                  </span>
                  <span className="flex items-center gap-2 text-orange-400 text-base font-semibold">
                    <FaLanguage /> {movie.language}
                  </span>
                </div>
                {/* Age rating highlight */}
                <div className="mb-4">
                  <span className="bg-orange-400 text-[#181a1f] font-bold px-3 py-1 rounded">
                    {movie.ageRating ? `${movie.ageRating}: Phim dành cho khán giả từ đủ ${movie.ageRating.replace(/\D/g, "") || "?"} tuổi trở lên (${movie.ageRating})` : ""}
                  </span>
                </div>
                {/* Director, Release, Company */}
                <div className="mb-2 flex flex-wrap gap-6 items-center">
                  <span className="flex items-center gap-2 text-gray-300 font-bold">
                    <FaUserTie className="text-lg" />
                    Đạo diễn:
                    <span className="text-white font-normal ml-1">{movie.director}</span>
                  </span>
                  <span className="flex items-center gap-2 text-gray-300 font-bold">
                    <FaCalendarAlt className="text-lg" />
                    Khởi chiếu:
                    <span className="text-white font-normal ml-1">{movie.releaseDate}</span>
                  </span>
                </div>
                <div className="mb-2 flex flex-wrap gap-6 items-center">
                  <span className="flex items-center gap-2 text-gray-300 font-bold">
                    <FaBuilding className="text-lg" />
                    Hãng sản xuất:
                    <span className="text-white font-normal ml-1">{movie.productionCompany}</span>
                  </span>
                </div>
                <div className="mb-2 flex flex-wrap gap-6 items-center">
                  <span className="flex items-center gap-2 text-gray-300 font-bold">
                    <FaUsers className="text-lg" />
                    Diễn viên:
                    <span className="text-white font-normal ml-1">{movie.actors}</span>
                  </span>
                </div>
                <div className="mb-2 flex flex-wrap gap-6 items-center">
                  <span className="flex items-center gap-2 text-gray-400 font-bold">
                    <FaCalendarCheck className="text-lg" />
                    Từ ngày:
                    <span className="text-white font-normal ml-1">{movie.fromDate || "Chưa có"}</span>
                  </span>
                  <span className="flex items-center gap-2 text-gray-400 font-bold">
                    <FaCalendarTimes className="text-lg" />
                    Đến ngày:
                    <span className="text-white font-normal ml-1">{movie.toDate || "Chưa có"}</span>
                  </span>
                </div>
                <div className="mb-2 flex flex-wrap gap-6 items-center">
                  <span className="flex items-center gap-2 text-orange-300 font-bold">
                    <FaSignal className="text-lg" />
                    Trạng thái:
                    <span className="text-white font-normal ml-1">{movie.status || "Chưa có"}</span>
                  </span>
                </div>
                {/* Description */}
                <div className="mt-6">
                  <div className="font-bold text-base mb-1 text-orange-400">MÔ TẢ</div>
                  <div className="text-gray-200">{movie.content}</div>
                </div>
              </div>
              {/* Trailer */}
              {movie.trailer && (
                <div className="mt-8">
                  <div className="font-semibold text-lg mb-2 flex items-center gap-2 text-orange-300">
                    <FaPlayCircle className="text-2xl" />
                    Trailer
                    <a
                      href={movie.trailer}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="ml-3 underline text-orange-200 hover:text-orange-400 transition"
                    >
                      Xem trên YouTube
                    </a>
                  </div>
                  {movie.trailer.includes("youtube.com") || movie.trailer.includes("youtu.be") ? (
                    <div className="aspect-video w-full max-w-xl rounded-lg overflow-hidden border border-gray-700 bg-black">
                      <iframe
                        src={
                          movie.trailer.includes("embed")
                            ? movie.trailer
                            : `https://www.youtube.com/embed/${movie.trailer.split("v=")[1]?.split("&")[0] || movie.trailer.split("/").pop()}`
                        }
                        title="Trailer"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        allowFullScreen
                        className="w-full h-full"
                      ></iframe>
                    </div>
                  ) : (
                    <a
                      href={movie.trailer}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-orange-400 hover:text-orange-500 font-semibold text-lg transition flex items-center gap-2 mt-2"
                    >
                      <FaPlayCircle className="text-2xl" />
                      Xem Trailer
                    </a>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
        {/* Booking Section + CommentManagement */}
        <div className="w-full max-w-4xl mx-auto mt-0">
          <BookingSection
            movie={movie}
            isComingSoon={isComingSoon}
            quickBooking={location.state?.quickBooking}
            bookingInfo={bookingInfo}
            setBookingInfo={setBookingInfo}
            onShowtimeChange={handleShowtimeChange}
            selectedFoods={selectedFoods}
            setSelectedFoods={setSelectedFoods}
          />
          {movie?.movieID && <CommentManagement movieId={movie.movieID} />}
        </div>
        {/* Chỉ hiển thị Snackbar khi đã chọn giờ */}
        {bookingInfo.time && (
          <Snackbar
            movieId={movie.movieID}
            movieTitle={bookingInfo.movieTitle}
            cinemaName={bookingInfo.cinemaName}
            cityName={bookingInfo.cityName}
            selectedSeats={bookingInfo.selectedSeats}
            totalPrice={bookingInfo.totalPrice}
            date={bookingInfo.date}
            time={bookingInfo.time}
            showtime={currentShowtime}
            onError={(errorMsg) => {
              console.error(errorMsg);
            }}
            disabled={
              isComingSoon ||
              !bookingInfo.cityName ||
              !bookingInfo.cinemaName ||
              !bookingInfo.date ||
              !bookingInfo.time ||
              bookingInfo.selectedSeats.length === 0
            }
            selectedFoods={selectedFoods}
          />
        )}
      </div>
    </div>
  );
};

export default MovieDetail;

import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { payWithPayOS } from "../../../service/payment";
import ParallaxBackground from '../LandingPage/ParallaxBackground';
import { CiSun } from 'react-icons/ci';

const localPaymentMethods = [
  { key: "payos", name: "PayOS" },
];

const PaymentMethod = ({ onSelect, defaultMethod }) => {
  const location = useLocation();
  const navigate = useNavigate();

  // Lấy dữ liệu từ location.state hoặc localStorage
  let stateData = location.state;
  if (!stateData) {
    // Fallback từ localStorage nếu không có location.state
    const bookingId = localStorage.getItem("bookingId");
    const totalMoney = localStorage.getItem("totalMoney");
    const cinemaRoomId = localStorage.getItem("cinemaRoomId");
    const seats = localStorage.getItem("seats");

    if (bookingId && totalMoney && cinemaRoomId && seats) {
      stateData = {
        bookingId: parseInt(bookingId),
        totalMoney: parseInt(totalMoney),
        cinemaRoomId: parseInt(cinemaRoomId),
        seats: JSON.parse(seats),
        usePointsPayment: false,
      };
    }
  }

  const paymentData = {
    ...stateData,
    cinemaRoomId: stateData?.cinemaRoomId || stateData?.bookingRequest?.cinemaRoomId,
  };




  const [selected, setSelected] = useState(defaultMethod || "");

  // Dark mode state synced với localStorage (giống các trang khác)
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const stored = localStorage.getItem('landing_dark_mode');
    return stored === 'true';
  });

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const handleSelect = (method) => {
    setSelected(method);
    if (onSelect) onSelect(method);
  };

  const handleContinue = async () => {
    console.log(" DEBUG - PaymentMethod handleContinue - paymentData:", paymentData);
    console.log(" DEBUG - PaymentMethod handleContinue - localStorage before payment:", {
      bookingId: localStorage.getItem("bookingId"),
      totalMoney: localStorage.getItem("totalMoney"),
      cinemaRoomId: localStorage.getItem("cinemaRoomId"),
      seats: localStorage.getItem("seats")
    });

    if (selected === "payos") {
      try {
        const res = await payWithPayOS(paymentData);
        if (res && res.result) {
          window.location.href = res.result;
        } else {
          alert("Không nhận được đường dẫn thanh toán!");
        }
      } catch (err) {
        alert(err?.response?.data?.message || "Thanh toán thất bại!");
      }
    }
    // ...xử lý các phương thức khác nếu có...
  };

  return (
    <div className="relative min-h-screen w-full">
      {/* Nút chuyển chế độ sáng/tối giống các trang khác */}
      <button
        onClick={() => {
          setIsDarkMode((prev) => {
            localStorage.setItem('landing_dark_mode', !prev);
            return !prev;
          });
        }}
        className="fixed top-20 right-1 z-[10000] w-8 h-8 flex items-center justify-center rounded-full shadow-lg hover:bg-gray-700 transition bg-orange-100 border-gray-600 focus:outline-none"
        aria-label={isDarkMode ? 'Chế độ Sáng' : 'Chế độ Tối'}
        title={isDarkMode ? 'Chế độ Sáng' : 'Chế độ Tối'}
      >
        <CiSun className={`w-7 h-7 transition-colors duration-200 ${isDarkMode ? 'text-black' : 'text-orange-400'}`} />
      </button>
      <ParallaxBackground isDarkMode={isDarkMode} />
      {/* Main content */}
      <div className="relative z-10 flex flex-col items-center py-10 min-h-screen">
        <div className="bg-white shadow-xl rounded-xl p-8 max-w-lg w-full border border-gray-200">
          <h2 className="text-xl mb-4 text-center">Chọn phương thức thanh toán</h2>
          <div
            className={`grid gap-4 mb-6 items-stretch ${
              localPaymentMethods.length === 1
                ? "grid-cols-1 place-items-center"
                : "grid-cols-2"
            }`}
          >
            {localPaymentMethods.map((method) => (
              <button
                key={method.key}
                className={`flex min-h-[150px] ${
                  localPaymentMethods.length === 1 ? "w-full max-w-[240px]" : "w-full"
                } flex-col items-center justify-center border rounded-lg p-4 transition
                  ${selected === method.key ? "border-blue-600 ring-2 ring-blue-200" : "border-gray-300"}
                  hover:border-blue-400`}
                onClick={() => handleSelect(method.key)}
                type="button"
              >
                {method.img ? (
                  <img src={method.img} alt={method.name} className="h-12 mb-2 object-contain" />
                ) : (
                  <div className="h-12 mb-2 flex items-center justify-center text-xl font-bold text-blue-600">
                    {method.name}
                  </div>
                )}
                <span className="font-medium">{method.name}</span>
                {selected === method.key && (
                  <span className="mt-2 text-blue-600 font-semibold text-sm">Đã chọn</span>
                )}
              </button>
            ))}
          </div>
          <div className="mt-6 flex gap-3">
            <button
              className="flex-1 bg-gray-300 text-black py-2 rounded hover:bg-gray-400 transition"
              onClick={() => navigate(-2)}
            >
              Quay về
            </button>
            <button
              className="flex-1 bg-gradient-to-r from-orange-600 to-yellow-500 hover:from-orange-500 hover:to-yellow-400 text-white py-2 rounded transition"
              disabled={!selected}
              onClick={handleContinue}
            >
              Tiếp tục
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

