          if (payosSuccess) {
            setStatus("success");
            setMessage("Thanh toán thành công!");
            clearPaymentStorage();
            localStorage.removeItem("selectedPromotionIds");
          } else {
            setStatus("fail");
            setMessage("Thanh toán thất bại hoặc bị hủy!");
