    </div>
    <div style={{ fontSize: 13, marginBottom: 2 }}>
      <b>Ghế:</b>{" "}
      {Array.isArray(order.seats) && order.seats.length > 0
        ? order.seats.map((seat) => seat.seatName).join(", ")
        : "Không có"}
    </div>
    <div style={{ fontSize: 13, marginBottom: 2 }}>
      <b>Tổng tiền:</b>{" "}
